SELECT COUNT(*)
FROM incident_assignment
WHERE incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND account_id = #{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND revoked_at IS NULL

SELECT COUNT(*)
FROM police_phone
WHERE id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND account_id = #{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND status = 'ACTIVE'
  AND registered = TRUE
